<?php include 'config.php'; $msg=''; if($_SERVER['REQUEST_METHOD']=='POST'){ $emp=(int)$_POST['employee_id']; $status=$_POST['status']; $date=date('Y-m-d'); if($emp<=0){$msg='Enter valid employee id';} else {$stmt=mysqli_prepare($conn,'INSERT INTO attendance(employee_id,date,status) VALUES(?,?,?)'); mysqli_stmt_bind_param($stmt,'iss',$emp,$date,$status); if(!mysqli_stmt_execute($stmt)) $msg='Attendance already marked for today'; else $msg='Attendance marked';}}
$where='1'; if(!empty($_GET['date'])) $where.=" AND date='".mysqli_real_escape_string($conn,$_GET['date'])."'"; if(!empty($_GET['employee_id'])) $where.=' AND employee_id='.(int)$_GET['employee_id']; $res=mysqli_query($conn,"SELECT * FROM attendance WHERE $where ORDER BY date DESC"); ?>
<!DOCTYPE html><html><head><title>Q15 Attendance</title><link rel="stylesheet" href="style.css"></head><body><div class="container"><h1>Employee Attendance System</h1><form method="post"><input name="employee_id" placeholder="Employee ID"><select name="status"><option>Present</option><option>Absent</option></select><button>Mark Attendance</button></form><p><?php echo $msg; ?></p><h2>Report</h2><form method="get"><input type="date" name="date"><input name="employee_id" placeholder="Employee ID"><button>Filter</button></form><table><tr><th>Employee</th><th>Date</th><th>Status</th></tr><?php while($r=mysqli_fetch_assoc($res)){ ?><tr><td><?php echo $r['employee_id']; ?></td><td><?php echo $r['date']; ?></td><td><?php echo $r['status']; ?></td></tr><?php } ?></table></div><script src="script.js"></script></body></html>
